import{_ as p,r as s,o,c as l,e as n,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Site Picker - October CMS - 4.x","titleTemplate":false,"description":"Tools for working with multiple site definitions","frontmatter":{"subtitle":"Tools for working with multiple site definitions"},"headers":[{"level":2,"title":"Basic Usage","slug":"basic-usage","link":"#basic-usage","children":[]},{"level":2,"title":"Loading Sites for a Different Page","slug":"loading-sites-for-a-different-page","link":"#loading-sites-for-a-different-page","children":[]},{"level":2,"title":"Translating URL Parameters","slug":"translating-url-parameters","link":"#translating-url-parameters","children":[{"level":3,"title":"Using the Multisite Trait","slug":"using-the-multisite-trait","link":"#using-the-multisite-trait","children":[]},{"level":3,"title":"Using the Translatable Trait","slug":"using-the-translatable-trait","link":"#using-the-translatable-trait","children":[]}]},{"level":2,"title":"Translating Query String Parameters","slug":"translating-query-string-parameters","link":"#translating-query-string-parameters","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/cms/components/sitepicker.md","filePath":"4.x/cms/components/sitepicker.md"}'),r={name:"4.x/cms/components/sitepicker.md"};function u(k,a,g,d,m,h){const t=s("pre-heading"),e=s("post-heading");return o(),l("div",null,[n(t),a[0]||(a[0]=c("h1",null,"Site Picker",-1)),n(e),a[1]||(a[1]=i(`<p>The <code>sitePicker</code> component provides tools for working with <a href="./../multisite/multisite.html">Multisite configuration</a> for your website. The best place to include this is in your page or layout template.</p><h2 id="basic-usage"><a href="#basic-usage" class="header-anchor">#</a> Basic Usage</h2><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">sitePicker</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> availableSites <span class="token operator">=</span> sitePicker<span class="token punctuation">.</span>sites <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>The following is an example of displaying a dropdown that switches between sites. It is used in conjunction with the <code>this.site</code> <a href="./../../markup/property/this-site.html">Twig property</a>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>select</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-control<span class="token punctuation">&quot;</span></span> <span class="token special-attr"><span class="token attr-name">onchange</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value javascript language-javascript">window<span class="token punctuation">.</span>location<span class="token punctuation">.</span><span class="token function">assign</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>value<span class="token punctuation">)</span></span><span class="token punctuation">&quot;</span></span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> site <span class="token operator">in</span> sitePicker<span class="token punctuation">.</span>sites <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>option</span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> site<span class="token punctuation">.</span>url <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name"><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> this<span class="token punctuation">.</span>site<span class="token punctuation">.</span>code <span class="token operator">==</span> site<span class="token punctuation">.</span>code <span class="token operator">?</span> <span class="token string"><span class="token punctuation">&#39;</span>selected<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">}}</span></span></span><span class="token punctuation">&gt;</span></span>
            <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> site<span class="token punctuation">.</span>name <span class="token delimiter punctuation">}}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>option</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>select</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Another example is generating alternative page links using meta tags</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> site <span class="token operator">in</span> sitePicker<span class="token punctuation">.</span>sites <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>link</span> <span class="token attr-name">rel</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alternate<span class="token punctuation">&quot;</span></span> <span class="token attr-name">hreflang</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> site<span class="token punctuation">.</span>locale <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> site<span class="token punctuation">.</span>url <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="loading-sites-for-a-different-page"><a href="#loading-sites-for-a-different-page" class="header-anchor">#</a> Loading Sites for a Different Page</h2><p>By default, the <code>sites</code> property will return sites configured for the current page and the <code>url</code> will resolve to the current page. The <code>pageSites()</code> function can be used to locate sites for a different page, where the first argument is the CMS page name.</p><p>In the example below, each site will have a <code>url</code> set to the CMS page found in <strong>pages/blog/index.htm</strong>. If the page is not found, then the result will be an empty array.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">sitePicker</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> otherSites <span class="token operator">=</span> sitePicker<span class="token punctuation">.</span>pageSites<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>blog/index<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h2 id="translating-url-parameters"><a href="#translating-url-parameters" class="header-anchor">#</a> Translating URL Parameters</h2><p>By default, the <code>sitePicker</code> component isn&#39;t aware of model parameters in the URL, such as page slugs and identifiers. The <code>cms.sitePicker.overrideParams</code> <a href="./../../extend/services/event.html">global event</a> is used to override the URL parameters to their translated versions. A good place to put this event is inside the <code>init</code> or the <code>onRun</code> method of a <a href="./../../extend/cms-components.html">CMS Component class</a>.</p><h3 id="using-the-multisite-trait"><a href="#using-the-multisite-trait" class="header-anchor">#</a> Using the Multisite Trait</h3><p>If the model implements the <a href="./../../extend/multisite/multisite.html"><code>Multisite</code> trait</a>, each site has a separate record with its own slug. The <code>newOtherSiteQuery</code> method is used to locate the model for the proposed site and modify the URL parameters.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$myModel</span> <span class="token operator">=</span> <span class="token class-name static-context">MyModel</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$otherModels</span> <span class="token operator">=</span> <span class="token variable">$myModel</span><span class="token operator">-&gt;</span><span class="token function">newOtherSiteQuery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.sitePicker.overrideParams&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$page</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">,</span> <span class="token variable">$currentSite</span><span class="token punctuation">,</span> <span class="token variable">$proposedSite</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$otherModels</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$otherModel</span> <span class="token operator">=</span> <span class="token variable">$otherModels</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_id&#39;</span><span class="token punctuation">,</span> <span class="token variable">$proposedSite</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$otherModel</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$params</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$otherModel</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">;</span>
        <span class="token variable">$params</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$otherModel</span><span class="token operator">-&gt;</span><span class="token property">slug</span><span class="token punctuation">;</span>
        <span class="token variable">$params</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;fullslug&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$otherModel</span><span class="token operator">-&gt;</span><span class="token property">fullslug</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">return</span> <span class="token variable">$params</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="using-the-translatable-trait"><a href="#using-the-translatable-trait" class="header-anchor">#</a> Using the Translatable Trait</h3><p>If the model implements the <a href="./../../extend/multisite/translatable.html"><code>Translatable</code> trait</a>, there is a single record with translated attributes. The <code>getTranslation</code> method retrieves the slug for the proposed locale.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$myModel</span> <span class="token operator">=</span> <span class="token class-name static-context">MyModel</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.sitePicker.overrideParams&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$page</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">,</span> <span class="token variable">$currentSite</span><span class="token punctuation">,</span> <span class="token variable">$proposedSite</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$myModel</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$proposedLocale</span> <span class="token operator">=</span> <span class="token variable">$proposedSite</span><span class="token operator">-&gt;</span><span class="token property">hard_locale</span><span class="token punctuation">;</span>
    <span class="token variable">$params</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;slug&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$myModel</span><span class="token operator">-&gt;</span><span class="token function">getTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;slug&#39;</span><span class="token punctuation">,</span> <span class="token variable">$proposedLocale</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token variable">$params</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="translating-query-string-parameters"><a href="#translating-query-string-parameters" class="header-anchor">#</a> Translating Query String Parameters</h2><p>The <code>cms.sitePicker.overrideQuery</code> <a href="./../../extend/services/event.html">global event</a> works the same way as <code>cms.sitePicker.overrideParams</code> but applies to query string parameters instead of URL route parameters. This is useful when model identifiers or filters are passed via the query string.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.sitePicker.overrideQuery&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$page</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">,</span> <span class="token variable">$currentSite</span><span class="token punctuation">,</span> <span class="token variable">$proposedSite</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Modify $params and return the translated query string values</span>
    <span class="token keyword">return</span> <span class="token variable">$params</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../multisite/multisite.html">Multisite</a></li><li><a href="./../../extend/multisite/translatable.html">Translatable</a></li></ul></div>`,24))])}const w=p(r,[["render",u]]);export{f as __pageData,w as default};
